package dev.codex.lastzhelper;
import java.io.*;import java.util.*;import org.json.*;
public final class TruckDiscoveryProbe {
 static class Value {String key;int tag;long address,raw;Value(String k,int t,long a,long r){key=k;tag=t;address=a;raw=r;}JSONObject json()throws Exception{JSONObject o=new JSONObject().put("key",key).put("tag",tag);if((tag&15)==5)o.put("table","0x"+Long.toHexString(raw));else if(tag==3)o.put("number",raw);else if(tag==19)o.put("number",Double.longBitsToDouble(raw));else if((tag&15)==1)o.put("boolean",tag==17);else if((tag&15)==4)try{o.put("string",StateProbe.luaString(raw));}catch(Exception ignored){}return o;}}
 static List<Value> rows(long table)throws Exception{int log=StateProbe.u8(table+11);if(log>18)throw new IOException("table bound");long nodes=StateProbe.ptr(table+24);List<Value> out=new ArrayList<>();for(int i=0;i<(1<<log);i++){long a=nodes+i*24L;int kt=StateProbe.u8(a+9),vt=StateProbe.u8(a+8);if((kt&15)==4&&(vt&15)!=0){try{out.add(new Value(StateProbe.luaString(StateProbe.ptr(a+16)),vt,a,StateProbe.ptr(a)));}catch(Exception ignored){}}}for(int i=0;i<(1<<log);i++){long a=nodes+i*24L;int kt=StateProbe.u8(a+9),vt=StateProbe.u8(a+8);if((kt&15)==3&&(vt&15)!=0){long k=StateProbe.ptr(a+16);out.add(new Value("#"+(kt==3?Long.toString(k):Double.toString(Double.longBitsToDouble(k))),vt,a,StateProbe.ptr(a)));}}long size=StateProbe.ptr(table+8)>>>32;long array=StateProbe.ptr(table+16);int limit=(int)Math.min(size,128);for(int i=0;i<limit&&! (array==0);i++){long a=array+i*16L;int tag=StateProbe.u8(a+8);if((tag&15)!=0)out.add(new Value("#"+(i+1),tag,a,StateProbe.ptr(a)));}return out;}
 static JSONArray describe(long t,int depth)throws Exception{JSONArray a=new JSONArray();int count=0;for(Value v:rows(t)){if(count++>100)break;JSONObject o=v.json();if(depth>0&&(v.tag&15)==5&&!v.key.matches("(?i).*(class_type|config|super).*"))o.put("fields",describe(v.raw,depth-1));a.put(o);}return a;}
 public static void main(String[] args){try{String cache=args[0];JSONObject state=StateProbe.snapshot(cache);String[] binding=StateProbe.text(cache).split(" ");long manager=Long.parseLong(binding[2],16);StateProbe.mem=new RandomAccessFile("/proc/"+state.getInt("pid")+"/mem","r");long L=StateProbe.ptr(StateProbe.ptr(manager+32)+16),g=StateProbe.ptr(L+24),registry=StateProbe.ptr(g+64),array=StateProbe.ptr(registry+16),globals=StateProbe.ptr(array+16);JSONArray matches=new JSONArray();for(Value v:rows(globals)){if(!v.key.matches("(?i).*(truck|train|railway|caravan|convoy|cargo|transport|plunder|datacenter|datamanager).*"))continue;JSONObject entry=v.json();if((v.tag&15)==5){JSONArray fields=new JSONArray();int count=0;for(Value f:rows(v.raw)){if(count++>=110)break;fields.put(f.json());}entry.put("fields",fields);}matches.put(entry);}JSONArray liveManagers=new JSONArray();long dc=StateProbe.ptr(StateProbe.findField(globals,"DataCenter"));for(String managerKey:new String[]{"LWTrainDataManager","LWMyStationDataManager","ItemTemplateManager"})try{long m=StateProbe.ptr(StateProbe.findField(dc,managerKey));JSONObject mo=new JSONObject().put("name",managerKey).put("fields",describe(m,1));if(managerKey.equals("LWTrainDataManager")){mo.put("enemyTruckData",describe(StateProbe.ptr(StateProbe.findField(m,"enemyTrucks")),3));}liveManagers.put(mo);}catch(Exception ignored){}JSONArray loadedMatches=new JSONArray();long pkg=StateProbe.ptr(StateProbe.findField(globals,"package")),loaded=StateProbe.ptr(StateProbe.findField(pkg,"loaded"));for(Value v:rows(loaded)){if(!v.key.matches("(?i).*(truck|train|railway|transport|trade|escort|caravan|plunder).*"))continue;JSONObject entry=v.json();if((v.tag&15)==5){JSONArray fields=new JSONArray();int count=0;for(Value f:rows(v.raw)){if(count++>=100)break;fields.put(f.json());}entry.put("fields",fields);}loadedMatches.put(entry);}long ui=StateProbe.ptr(StateProbe.findField(globals,"UIManagerInstance")),windows=StateProbe.ptr(StateProbe.findField(ui,"windows"));JSONArray uiWindows=new JSONArray();for(Value v:rows(windows)){JSONObject entry=v.json();if((v.tag&15)==5){JSONArray fields=new JSONArray();for(Value f:rows(v.raw))fields.put(f.json());entry.put("fields",fields);if(v.key.equals("UILWTrainScene")){entry.put("liveView",describe(StateProbe.ptr(StateProbe.findField(v.raw,"View")),2));entry.put("liveCtrl",describe(StateProbe.ptr(StateProbe.findField(v.raw,"Ctrl")),1));long view=StateProbe.ptr(StateProbe.findField(v.raw,"View"));entry.put("trainListData",describe(StateProbe.ptr(StateProbe.findField(view,"trainList")),2));}}uiWindows.put(entry);}System.out.println(new JSONObject().put("state",state).put("truckGlobals",matches).put("loadedTruckModules",loadedMatches).put("uiWindows",uiWindows).put("liveManagers",liveManagers).toString(2));StateProbe.mem.close();}catch(Throwable e){try{System.out.println(new JSONObject().put("ok",false).put("error",e.toString()).toString(2));}catch(Exception ignored){}System.exit(1);}}
}

